/** CpfSmsNotificationAdapter 타입의 역할과 책임을 정의하며 CPF 계약 경계를 명확히 유지한다. */
package com.cpf.notification.dispatch.sms.spi;import com.cpf.notification.dispatch.*;public final class CpfSmsNotificationAdapter implements CpfNotificationProvider {private final CpfSmsDispatcher dispatcher;public CpfSmsNotificationAdapter(CpfSmsDispatcher d){dispatcher=d;}public String channel(){return "SMS";}public CpfNotificationResult send(CpfNotificationRequest r){var x=dispatcher.send(r.recipient(),r.variables().getOrDefault("body",""),r.idempotencyKey());return new CpfNotificationResult(r.notificationId(),"SMS",x.status(),x.providerMessageId(),x.detail(),java.time.Instant.now());}}
